#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NumpyDType {
    Bool,
    Int8,
    Int16,
    Int32,
    Int64,
    Float32,
    Float64,
    Complex64,
    Complex128,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum NumpyOperand {
    Scalar(NumpyDType),
    Array(NumpyDType),
}

fn dtype_rank(dt: NumpyDType) -> u8 {
    match dt {
        NumpyDType::Bool => 0,
        NumpyDType::Int8 => 1,
        NumpyDType::Int16 => 2,
        NumpyDType::Int32 => 3,
        NumpyDType::Int64 => 4,
        NumpyDType::Float32 => 5,
        NumpyDType::Float64 => 6,
        NumpyDType::Complex64 => 7,
        NumpyDType::Complex128 => 8,
    }
}

fn dtype_from_rank(r: u8) -> NumpyDType {
    match r {
        0 => NumpyDType::Bool,
        1 => NumpyDType::Int8,
        2 => NumpyDType::Int16,
        3 => NumpyDType::Int32,
        4 => NumpyDType::Int64,
        5 => NumpyDType::Float32,
        6 => NumpyDType::Float64,
        7 => NumpyDType::Complex64,
        _ => NumpyDType::Complex128, // covers 8 and any higher
    }
}

fn operand_dtype(op: &NumpyOperand) -> NumpyDType {
    match *op {
        NumpyOperand::Scalar(dt) | NumpyOperand::Array(dt) => dt,
    }
}

/// Returns the maximum-ranked dtype among the operands.
/// Assumes `operands` is non-empty as stated in the problem.
pub fn result_type(operands: Vec<NumpyOperand>) -> NumpyDType {
    let mut max_rank = 0u8;
    for op in &operands {
        let r = dtype_rank(operand_dtype(op));
        if r > max_rank {
            max_rank = r;
        }
    }
    dtype_from_rank(max_rank)
}